class RecordingLedger implements Ledger {
  private readonly balances = new Map<string, number>();
  private readonly journal: Operation[] = [];

  deposit(id: string, amount: number): void {
    this.balances.set(id, (this.balances.get(id) ?? 0) + amount); // behaviour
    this.journal.push({ op: 'deposit', id, amount });             // recorded
  }

  recorded(): readonly Operation[] { return [...this.journal]; }  // test accessor
}
